<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class DormitoryAssetController extends Controller{
private function manage(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('dormitory_manager')||$r->user()->canDo('dormitory.manage'),403);}
public function index(Request $r,$room){$this->manage($r);$rm=DB::table('dormitory_rooms as r')->join('dormitory_buildings as b','b.id','=','r.dormitory_building_id')->where('r.id',$room)->select('r.*','b.name as building_name')->first();abort_if(!$rm,404);$rows=DB::table('dormitory_assets')->where('dormitory_room_id',$room)->orderBy('name')->get();$stays=DB::table('dormitory_stays as st')->join('students as s','s.id','=','st.student_id')->join('dormitory_places as p','p.id','=','st.dormitory_place_id')->where('p.dormitory_room_id',$room)->where('st.status','active')->select('st.id','s.last_name','s.first_name')->get();return view('dormitory.assets',compact('rm','rows','stays'));}
public function store(Request $r,$room){$this->manage($r);$d=$r->validate(['name'=>'required|string|max:255','inventory_number'=>'nullable|string|max:100|unique:dormitory_assets,inventory_number','quantity'=>'required|integer|min:1','condition'=>'required|in:good,satisfactory,repair,writeoff','value'=>'nullable|numeric|min:0','note'=>'nullable|string|max:2000']);DB::table('dormitory_assets')->insert($d+['dormitory_room_id'=>$room,'created_at'=>now(),'updated_at'=>now()]);return back();}
public function act(Request $r,$room){$this->manage($r);$d=$r->validate(['dormitory_stay_id'=>'required|exists:dormitory_stays,id','act_number'=>'required|string|max:100','act_on'=>'required|date','type'=>'required|in:handover,return,inventory','asset_ids'=>'required|array|min:1','asset_ids.*'=>'exists:dormitory_assets,id']);$id=DB::transaction(function()use($d,$r,$room){$id=DB::table('dormitory_asset_acts')->insertGetId(['dormitory_stay_id'=>$d['dormitory_stay_id'],'act_number'=>$d['act_number'],'act_on'=>$d['act_on'],'type'=>$d['type'],'created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);foreach($d['asset_ids'] as $aid){$a=DB::table('dormitory_assets')->where(['id'=>$aid,'dormitory_room_id'=>$room])->first();if($a)DB::table('dormitory_asset_act_items')->insert(['dormitory_asset_act_id'=>$id,'dormitory_asset_id'=>$aid,'quantity'=>$a->quantity,'condition'=>$a->condition,'created_at'=>now(),'updated_at'=>now()]);}return $id;});return redirect()->route('dormitory.asset.act.print',$id);}
public function printAct(Request $r,$id){$this->manage($r);$act=DB::table('dormitory_asset_acts as a')->join('dormitory_stays as st','st.id','=','a.dormitory_stay_id')->join('students as s','s.id','=','st.student_id')->join('dormitory_places as p','p.id','=','st.dormitory_place_id')->join('dormitory_rooms as rm','rm.id','=','p.dormitory_room_id')->join('dormitory_buildings as b','b.id','=','rm.dormitory_building_id')->where('a.id',$id)->select('a.*','s.last_name','s.first_name','s.middle_name','rm.number as room_number','b.name as building_name')->first();abort_if(!$act,404);$items=DB::table('dormitory_asset_act_items as i')->join('dormitory_assets as a','a.id','=','i.dormitory_asset_id')->where('i.dormitory_asset_act_id',$id)->select('i.*','a.name','a.inventory_number')->get();return view('dormitory.asset-act-print',compact('act','items'));}
}